<!-- This file is generated by AI. -->

<!--
  快照打包对话框: 把整个项目打成一个可分发/可回滚的压缩包。

  流程按 `pack_snapshot` 的事件流走 (扫描 → 打包), 因此界面分两段进度: 先"正在收集 <文件名> ·
  N 个文件", 再"正在打包 M / N" —— 扫描阶段的总量在扫完之前不知道, 给不了从头到尾的百分比。

  关闭时**不打断打包**: 打包在后端跑, 关掉对话框只是不再看进度 (真要中止得退出应用), 因此
  「关闭」按钮在打包中保持可用。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import { save } from '@tauri-apps/plugin-dialog';
  import { openPath } from '@tauri-apps/plugin-opener';

  import { packSnapshot, type SnapshotEvent, type SnapshotResult } from '../commands/snapshot';
  import { appStore } from '../state/store.svelte';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import Icon from './Icon.svelte';

  let { onClose }: { onClose: () => void } = $props();

  const projectPath = $derived(appStore.projectPath);
  const projectName = $derived(appStore.projectName ?? 'project');

  /** 输出路径草稿; 默认放在项目同级, 名字取项目名 */
  let destination = $state('');

  let phase = $state<'idle' | 'scanning' | 'packing' | 'done' | 'failed'>('idle');
  let scanned = $state(0);
  let scanSize = $state(0);
  /** 当前正在扫描的文件 (取最后一段); 扫描阶段唯一能让用户看出"还在动"的东西 */
  let scanFile = $state('');
  let packed = $state(0);
  let packCount = $state(0);
  let packSize = $state(0);
  let compressed = $state(0);
  let finalSize = $state(0);
  let errors = $state<string[]>([]);
  let result = $state<SnapshotResult | null>(null);

  /** 进度条百分比: 扫描阶段没有总量, 因此只显示已扫数量, 不画进度条。 */
  const percent = $derived(packCount > 0 ? Math.min(100, Math.round((packed / packCount) * 100)) : 0);
  const running = $derived(phase === 'scanning' || phase === 'packing');

  const defaultDestination = $derived(
    (() => {
      const path = projectPath;
      if (!path) return '';
      const separator = path.includes('\\') ? '\\' : '/';
      const parent = path.slice(0, path.length - (path.split(/[\\/]/).pop()?.length ?? 0));
      return `${parent}${parent.endsWith(separator) ? '' : separator}${projectName}.zip`;
    })()
  );

  // 初值只在挂载时取一次
  destination = (() => defaultDestination)();

  function formatSize(bytes: number): string {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
  }

  function handleEvent(event: SnapshotEvent): void {
    switch (event.type) {
      case 'scanStart':
        phase = 'scanning';
        scanned = 0;
        break;
      case 'scanFile':
        scanned = event.index + 1;
        scanSize = event.cumulativeSize;
        scanFile = event.path.split(/[\\/]/).pop() ?? event.path;
        break;
      case 'scanComplete':
        packCount = event.count;
        packSize = event.totalSize;
        break;
      case 'packStart':
        phase = 'packing';
        packCount = event.count;
        packSize = event.totalSize;
        break;
      case 'packFile':
        packed = event.index + 1;
        compressed = event.cumulativeCompressedSize;
        break;
      case 'packComplete':
        finalSize = event.finalSize;
        break;
      case 'scanError':
      case 'packError':
        errors = [...errors, event.message];
        break;
    }
  }

  async function pickDestination(): Promise<void> {
    try {
      const chosen = await save({
        title: '保存快照',
        defaultPath: destination || defaultDestination,
        filters: [{ name: '压缩包', extensions: ['zip'] }],
      });
      if (chosen) destination = chosen;
    } catch {
      // 用户取消不是错误
    }
  }

  async function pack(): Promise<void> {
    const source = projectPath;
    const target = destination.trim();
    if (!source || !target) return;

    phase = 'scanning';
    scanned = 0;
    scanSize = 0;
    scanFile = '';
    packed = 0;
    packCount = 0;
    packSize = 0;
    compressed = 0;
    finalSize = 0;
    errors = [];
    result = null;

    try {
      result = await packSnapshot(source, target, handleEvent);
      errors = result.errors;
      finalSize = result.finalSize;
      phase = result.aborted ? 'failed' : 'done';
    } catch (error) {
      errors = [String(error)];
      phase = 'failed';
    }
  }

  async function openContainingFolder(): Promise<void> {
    const target = result ? destination : destination;
    if (!target) return;
    try {
      // 没有"在文件管理器里选中文件"的 command, 打开所在目录是等价且够用的做法
      const separator = target.includes('\\') ? '\\' : '/';
      const parent = target.slice(0, target.lastIndexOf(separator));
      await openPath(parent || target);
    } catch (error) {
      errors = [...errors, String(error)];
    }
  }
</script>

<AppDialog title="生成快照" iconName="Archive" size="medium" closeOnBackdrop={!running} {onClose}>
  <div class="snapshot-body">
    <!--
      打包规则必须先讲清楚: 快照是**精简打包** —— 只放被语句与配置引用到的资源,
      未引用的资源不会进包。不说的话用户会以为包是坏的。
    -->
    <p class="snapshot-intro">从初始场景 start.txt 和配置出发，收集引用到的资源，其余文件原样保留。</p>

    <p class="snapshot-note">
      <strong>变量插值拼出的资源名不会进包</strong>
      <!--
        这里的花括号必须写成实体 (`&#123;` / `&#125;`) —— Svelte 模板里的 `{...}` 是**表达式**,
        直接写 `bg:{bgName}` 会被当成变量名 `bgName`, 编译期报 "Cannot find name"。
      -->
      ：bg:&#123;bgName&#125;、callScene:&#123;chapter&#125; 这类名字打包器只看到字面量，资源找不到也不会被打包。请改用字面量，或打包后手动补进压缩包。
    </p>

    <div class="settings-group">
      <h3>打包内容</h3>
      <div class="settings-field">
        <span class="settings-label">输出到</span>
        <!--
          只读路径字段 + 单图标浏览按钮, 用的是全应用统一的 `.input-row` (输入框在左、按钮在右,
          `align-items: stretch` 保证两者同高)。`readonly` 是因为路径必须来自"浏览"按钮; 用原生
          `<input>` 而不是 `ui/Input.svelte` (后者没有暴露 `readonly`), 类名仍是 `.ui-input`。
        -->
        <div class="input-row">
          <input
            class="ui-input"
            readonly
            value={destination}
            placeholder="选择快照压缩包的输出位置"
            title={destination}
            disabled={running}
          />
          <Button icon="FolderOpen" title="选择输出位置" disabled={running} onclick={() => void pickDestination()} />
        </div>
      </div>
    </div>

    {#if phase !== 'idle'}
      <div class="settings-group">
        <h3>
          {#if phase === 'scanning'}正在扫描…
          {:else if phase === 'packing'}正在打包…
          {:else if phase === 'done'}打包完成
          {:else}打包失败{/if}
        </h3>

        {#if phase === 'scanning'}
          <!-- 扫描阶段没有总量, 因此只能显示"正在收集哪个文件" + 已扫数量 -->
          <p class="snapshot-line">
            正在收集 {scanFile || '…'} · {scanned} 个文件 · {formatSize(scanSize)}
          </p>
        {:else if phase === 'packing'}
          <div class="snapshot-progress">
            <div class="snapshot-progress-fill" style="width:{percent}%"></div>
          </div>
          <p class="muted">
            {packed} / {packCount} 个文件 · 已压缩 {formatSize(compressed)} / 原始 {formatSize(packSize)}
          </p>
        {:else if phase === 'done'}
          <p class="muted">
            {result?.count ?? 0} 个文件 · 原始 {formatSize(result?.totalSize ?? 0)} → 压缩后 {formatSize(finalSize)}
          </p>
        {/if}

        {#if errors.length > 0}
          <div class="snapshot-errors">
            <p class="snapshot-errors-head">
              <Icon name="Warning" size={14} />
              {errors.length} 个问题
            </p>
            <ul>
              {#each errors.slice(0, 50) as message, index (index)}
                <li>{message}</li>
              {/each}
            </ul>
            {#if errors.length > 50}
              <p class="muted">还有 {errors.length - 50} 条未显示。</p>
            {/if}
          </div>
        {/if}
      </div>
    {/if}
  </div>

  {#snippet footer()}
    {#if phase === 'done'}
      <Button icon="FolderOpen" onclick={() => void openContainingFolder()}>打开所在目录</Button>
    {/if}
    <!-- 打包中**允许**关闭: 打包在后端跑, 关掉对话框只是不再看进度 (见文件头契约) -->
    <Button onclick={onClose}>关闭</Button>
    {#if phase === 'idle' || phase === 'failed'}
      <Button
        appearance="primary"
        icon="Archive"
        disabled={!projectPath || !destination.trim()}
        onclick={() => void pack()}
      >
        开始打包
      </Button>
    {/if}
  {/snippet}
</AppDialog>
